-- 001_core.sql: core schema v0 (Tier 1)
-- Implements accepted decisions D-001 to D-004 (docs/decisions/) and the status rules in CLAUDE.md.
--
-- Key idea (D-001): rows record what one source REPORTED. A physical diamond or inclusion is a
-- cluster of observations joined by approved identity links (views at the bottom); rows are never merged.
--
-- Portability (D-004): plain types and CHECK constraints so the same file loads in PostgreSQL.
-- Known PostgreSQL diff: INTEGER PRIMARY KEY auto-numbers only in SQLite; use
-- "INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY" there.
-- SQLite: every connection that writes must run PRAGMA foreign_keys = ON.
--
-- Shared value lists (repeated as CHECKs, since SQLite has no enum type):
--   value_status    reported | not_reported | not_measured | not_applicable | unknown | ambiguous | below_detection
--   derivation      reported | calculated_by_authors | calculated_by_compiler | calculated_by_us | inferred | interpreted
--   workflow_status not_attempted | extracted | imported_unverified | extraction_failed | pending_review
--                   | approved | rejected | superseded


-- ============ 1. Controlled vocabularies ============

CREATE TABLE unit (
    code        TEXT PRIMARY KEY,           -- e.g. 'wt%', 'ppm', 'at_ppm', 'permil', 'cm-1', 'GPa', 'degC', 'Ma'
    dimension   TEXT NOT NULL,              -- e.g. 'mass_fraction', 'temperature'
    description TEXT
);

CREATE TABLE method (
    code        TEXT PRIMARY KEY,           -- e.g. 'EPMA', 'SIMS', 'LA-ICP-MS', 'FTIR', 'Raman', 'XRD', 'TIMS'
    name        TEXT NOT NULL,
    description TEXT
);

-- Anything with a number: oxides, elements, isotope ratios, deltas, spectral and derived quantities.
CREATE TABLE quantity (
    code         TEXT PRIMARY KEY,          -- e.g. 'SiO2', 'La', 'd13C', '187Os/188Os', 'N_total', 'T_equilibration'
    kind         TEXT NOT NULL CHECK (kind IN ('oxide', 'element', 'isotope_ratio', 'isotope_delta',
                                               'concentration', 'spectral', 'derived', 'other')),
    default_unit TEXT REFERENCES unit(code),
    description  TEXT
);

-- Properties that assertions can state: interpretations and descriptive attributes.
CREATE TABLE property (
    code        TEXT PRIMARY KEY,           -- e.g. 'paragenesis', 'inferred_original_phase', 'garnet_class',
                                            --      'craton', 'collection_locality', 'size', 'shape', 'touching'
    applies_to  TEXT NOT NULL CHECK (applies_to IN ('inclusion', 'diamond', 'inclusion_set', 'any')),
    description TEXT
);

CREATE TABLE phase (
    id              INTEGER PRIMARY KEY,
    name            TEXT NOT NULL UNIQUE,   -- standardized name
    phase_kind      TEXT NOT NULL CHECK (phase_kind IN ('mineral_species', 'variety', 'solid_solution',
                                                        'composition_only', 'polyphase', 'fluid', 'unknown')),
    parent_phase_id INTEGER REFERENCES phase(id),   -- e.g. a variety's species
    formula         TEXT,
    ima_status      TEXT,
    mindat_id       TEXT,
    notes           TEXT
);

-- Names as printed in sources, mapped to a phase: 'garnet (maj)', 'CaSiO3-walstromite', 'breyite'.
CREATE TABLE phase_name_variant (
    id           INTEGER PRIMARY KEY,
    phase_id     INTEGER NOT NULL REFERENCES phase(id),
    variant      TEXT NOT NULL UNIQUE,
    variant_type TEXT NOT NULL CHECK (variant_type IN ('synonym', 'abbreviation', 'historical',
                                                       'spelling', 'compiler_label')),
    notes        TEXT
);


-- ============ 2. Sources and provenance (D-002) ============

CREATE TABLE publication (
    id        INTEGER PRIMARY KEY,
    doi       TEXT UNIQUE,
    citation  TEXT NOT NULL,                -- full reference, verified
    short_ref TEXT,                         -- e.g. 'Phillips et al. (2004)'
    year      INTEGER,
    pub_type  TEXT NOT NULL CHECK (pub_type IN ('journal_article', 'book_chapter', 'book', 'thesis',
                                                'conference_abstract', 'dataset', 'report',
                                                'unpublished', 'other')),
    notes     TEXT
);

CREATE TABLE source_file (
    id             INTEGER PRIMARY KEY,
    publication_id INTEGER NOT NULL REFERENCES publication(id),
    file_role      TEXT NOT NULL CHECK (file_role IN ('main_text', 'supplement', 'compilation',
                                                      'raw_data', 'other')),
    filename       TEXT NOT NULL,
    md5            TEXT,
    url            TEXT,
    notes          TEXT
);

CREATE TABLE import_run (
    id           INTEGER PRIMARY KEY,
    run_type     TEXT NOT NULL CHECK (run_type IN ('manual_curation', 'claude_extraction',
                                                   'compilation_import', 'other')),
    started_at   TEXT NOT NULL,             -- ISO 8601
    tool         TEXT,
    tool_version TEXT,
    operator     TEXT,
    notes        TEXT
);

-- Where something was found. Shared by all values of one measurement or one assertion (D-002).
CREATE TABLE evidence (
    id                   INTEGER PRIMARY KEY,
    publication_id       INTEGER NOT NULL REFERENCES publication(id),
    source_file_id       INTEGER REFERENCES source_file(id),
    source_type          TEXT NOT NULL CHECK (source_type IN ('paper', 'supplement', 'compilation',
                                                              'personal_communication', 'unpublished',
                                                              'gazetteer')),
    page                 TEXT,
    table_label          TEXT,
    figure_label         TEXT,
    sheet                TEXT,
    row_label            TEXT,
    column_label         TEXT,
    excerpt              TEXT CHECK (excerpt IS NULL OR length(excerpt) <= 500),  -- short excerpts only (copyright)
    cited_publication_id INTEGER REFERENCES publication(id),  -- compilations: the paper the compiler cited
    cited_reference_text TEXT,              -- the compiler's citation string, as printed
    import_run_id        INTEGER REFERENCES import_run(id)
);


-- ============ 3. Localities (gazetteer; matching a diamond to one is an assertion) ============

CREATE TABLE locality (
    id                     INTEGER PRIMARY KEY,
    name                   TEXT NOT NULL,   -- standardized
    locality_type          TEXT NOT NULL CHECK (locality_type IN ('mine', 'pipe', 'dyke', 'prospect',
                                                                  'alluvial_deposit', 'field', 'district',
                                                                  'region', 'country', 'unknown', 'other')),
    parent_id              INTEGER REFERENCES locality(id),
    country_code           TEXT,            -- ISO 3166-1 alpha-2
    latitude               DOUBLE PRECISION CHECK (latitude BETWEEN -90 AND 90),
    longitude              DOUBLE PRECISION CHECK (longitude BETWEEN -180 AND 180),
    crs                    TEXT,
    precision_class        TEXT NOT NULL CHECK (precision_class IN ('exact', 'approximate', 'region',
                                                                    'ambiguous', 'unknown')),
    coordinate_evidence_id INTEGER REFERENCES evidence(id),
    external_id            TEXT,            -- e.g. Mindat or GeoNames id
    notes                  TEXT,
    CHECK ((latitude IS NULL AND longitude IS NULL) OR (latitude IS NOT NULL AND longitude IS NOT NULL)),
    -- coordinates always carry a CRS and a source; ambiguous/unknown places never get coordinates
    CHECK (latitude IS NULL OR (crs IS NOT NULL AND coordinate_evidence_id IS NOT NULL)),
    CHECK (latitude IS NULL OR precision_class NOT IN ('ambiguous', 'unknown'))
);

CREATE TABLE locality_alias (
    id          INTEGER PRIMARY KEY,
    locality_id INTEGER NOT NULL REFERENCES locality(id),
    alias       TEXT NOT NULL,
    alias_type  TEXT NOT NULL CHECK (alias_type IN ('historical', 'spelling', 'local_language',
                                                    'abbreviation', 'other')),
    UNIQUE (locality_id, alias)
);


-- ============ 4. Observations and identity (D-001) ============

-- One host diamond as reported by one source.
CREATE TABLE diamond_observation (
    id                INTEGER PRIMARY KEY,
    publication_id    INTEGER NOT NULL REFERENCES publication(id),
    evidence_id       INTEGER NOT NULL REFERENCES evidence(id),
    reported_locality TEXT,                 -- as printed
    workflow_status   TEXT NOT NULL DEFAULT 'pending_review'
                      CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                 'extraction_failed', 'pending_review', 'approved',
                                                 'rejected', 'superseded')),
    import_run_id     INTEGER REFERENCES import_run(id),
    notes             TEXT
);

CREATE TABLE specimen_identifier (
    id                     INTEGER PRIMARY KEY,
    diamond_observation_id INTEGER NOT NULL REFERENCES diamond_observation(id),
    identifier             TEXT NOT NULL,   -- as printed
    normalized             TEXT,            -- e.g. compiler's zero-padded form
    id_type                TEXT NOT NULL CHECK (id_type IN ('author_sample', 'collection', 'museum',
                                                            'igsn', 'other')),
    UNIQUE (diamond_observation_id, identifier)
);

-- One inclusion as reported by one source.
CREATE TABLE inclusion_observation (
    id                     INTEGER PRIMARY KEY,
    publication_id         INTEGER NOT NULL REFERENCES publication(id),
    evidence_id            INTEGER NOT NULL REFERENCES evidence(id),
    diamond_observation_id INTEGER REFERENCES diamond_observation(id),  -- NULL = host not reported
    reported_label         TEXT,            -- inclusion label as printed, e.g. '-a', '(1)'
    reported_phase         TEXT NOT NULL,   -- phase name as printed
    phase_id               INTEGER REFERENCES phase(id),  -- observed phase, standardized; NULL until mapped
    phase_match_status     TEXT NOT NULL DEFAULT 'unmapped'
                           CHECK (phase_match_status IN ('unmapped', 'mapped', 'ambiguous')),
    workflow_status        TEXT NOT NULL DEFAULT 'pending_review'
                           CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                      'extraction_failed', 'pending_review', 'approved',
                                                      'rejected', 'superseded')),
    import_run_id          INTEGER REFERENCES import_run(id),
    notes                  TEXT,
    CHECK (phase_match_status <> 'mapped' OR phase_id IS NOT NULL)
);

-- "These two observations are the same physical object", with its basis. Stored once per pair (a < b).
CREATE TABLE diamond_identity_link (
    id              INTEGER PRIMARY KEY,
    observation_a   INTEGER NOT NULL REFERENCES diamond_observation(id),
    observation_b   INTEGER NOT NULL REFERENCES diamond_observation(id),
    basis           TEXT NOT NULL CHECK (basis IN ('shared_sample_id', 'explicit_cross_reference',
                                                   'same_collection', 'compiler_derived', 'other')),
    asserted_by     TEXT NOT NULL CHECK (asserted_by IN ('authors', 'compiler', 'curator')),
    confidence      TEXT NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
    evidence_id     INTEGER REFERENCES evidence(id),
    workflow_status TEXT NOT NULL DEFAULT 'pending_review'
                    CHECK (workflow_status IN ('pending_review', 'approved', 'rejected', 'superseded')),
    notes           TEXT,
    CHECK (observation_a < observation_b),
    UNIQUE (observation_a, observation_b)
);

CREATE TABLE inclusion_identity_link (
    id              INTEGER PRIMARY KEY,
    observation_a   INTEGER NOT NULL REFERENCES inclusion_observation(id),
    observation_b   INTEGER NOT NULL REFERENCES inclusion_observation(id),
    basis           TEXT NOT NULL CHECK (basis IN ('shared_sample_id', 'explicit_cross_reference',
                                                   'same_collection', 'compiler_derived', 'other')),
    asserted_by     TEXT NOT NULL CHECK (asserted_by IN ('authors', 'compiler', 'curator')),
    confidence      TEXT NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
    evidence_id     INTEGER REFERENCES evidence(id),
    workflow_status TEXT NOT NULL DEFAULT 'pending_review'
                    CHECK (workflow_status IN ('pending_review', 'approved', 'rejected', 'superseded')),
    notes           TEXT,
    CHECK (observation_a < observation_b),
    UNIQUE (observation_a, observation_b)
);

-- Groups of inclusions that a result belongs to as a whole (isochrons, pooled analyses).
-- Statistic types (mean, range, n) are left to D-006, still open.
CREATE TABLE inclusion_set (
    id             INTEGER PRIMARY KEY,
    publication_id INTEGER NOT NULL REFERENCES publication(id),
    evidence_id    INTEGER NOT NULL REFERENCES evidence(id),
    label          TEXT NOT NULL,
    description    TEXT
);

CREATE TABLE inclusion_set_member (
    inclusion_set_id         INTEGER NOT NULL REFERENCES inclusion_set(id),
    inclusion_observation_id INTEGER NOT NULL REFERENCES inclusion_observation(id),
    PRIMARY KEY (inclusion_set_id, inclusion_observation_id)
);


-- ============ 5. Measurements (D-003) ============

-- One analysis (e.g. one EPMA spot, one FTIR spectrum) of one inclusion or one diamond.
CREATE TABLE measurement (
    id                       INTEGER PRIMARY KEY,
    inclusion_observation_id INTEGER REFERENCES inclusion_observation(id),
    diamond_observation_id   INTEGER REFERENCES diamond_observation(id),
    method_code              TEXT REFERENCES method(code),   -- NULL = method not reported
    spot_label               TEXT,          -- e.g. 'core', 'rim', '(1)'
    conditions               TEXT,          -- as reported: beam, spot size, standards
    evidence_id              INTEGER NOT NULL REFERENCES evidence(id),
    workflow_status          TEXT NOT NULL DEFAULT 'pending_review'
                             CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                        'extraction_failed', 'pending_review', 'approved',
                                                        'rejected', 'superseded')),
    import_run_id            INTEGER REFERENCES import_run(id),
    notes                    TEXT,
    CHECK ((CASE WHEN inclusion_observation_id IS NULL THEN 0 ELSE 1 END)
         + (CASE WHEN diamond_observation_id   IS NULL THEN 0 ELSE 1 END) = 1)
);

-- One value of one quantity in one measurement (long format).
CREATE TABLE measured_value (
    id               INTEGER PRIMARY KEY,
    measurement_id   INTEGER NOT NULL REFERENCES measurement(id),
    quantity_code    TEXT NOT NULL REFERENCES quantity(code),
    original_text    TEXT NOT NULL,         -- exactly as printed: '41.2', 'b.d.', '<0.02', ''
    original_unit    TEXT,                  -- as printed
    value            DOUBLE PRECISION,      -- parsed number; present only when value_status = 'reported'
    uncertainty      DOUBLE PRECISION,
    uncertainty_type TEXT CHECK (uncertainty_type IN ('1sd', '2sd', '1se', '2se', 'range', 'other')),
    detection_limit  DOUBLE PRECISION,
    value_status     TEXT NOT NULL CHECK (value_status IN ('reported', 'not_reported', 'not_measured',
                                                           'not_applicable', 'unknown', 'ambiguous',
                                                           'below_detection')),
    derivation       TEXT NOT NULL CHECK (derivation IN ('reported', 'calculated_by_authors',
                                                         'calculated_by_compiler', 'calculated_by_us',
                                                         'inferred', 'interpreted')),
    normalized_value DOUBLE PRECISION,
    normalized_unit  TEXT REFERENCES unit(code),
    conversion_rule  TEXT,                  -- id/version of the rule that produced normalized_value
    evidence_id      INTEGER REFERENCES evidence(id),  -- only when this value's source differs from its measurement's
    workflow_status  TEXT NOT NULL DEFAULT 'pending_review'
                     CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                'extraction_failed', 'pending_review', 'approved',
                                                'rejected', 'superseded')),
    CHECK ((value_status = 'reported' AND value IS NOT NULL) OR (value_status <> 'reported' AND value IS NULL)),
    CHECK (detection_limit IS NULL OR value_status IN ('below_detection', 'reported')),
    CHECK (uncertainty IS NULL OR uncertainty_type IS NOT NULL),
    CHECK (normalized_value IS NULL OR (normalized_unit IS NOT NULL AND conversion_rule IS NOT NULL)),
    UNIQUE (measurement_id, quantity_code)
);

-- Peaks and bands from a spectroscopic measurement.
CREATE TABLE spectral_feature (
    id             INTEGER PRIMARY KEY,
    measurement_id INTEGER NOT NULL REFERENCES measurement(id),
    original_text  TEXT NOT NULL,           -- as printed
    position       DOUBLE PRECISION,
    position_unit  TEXT REFERENCES unit(code),
    intensity      DOUBLE PRECISION,
    intensity_type TEXT CHECK (intensity_type IN ('height', 'area', 'relative', 'other')),
    intensity_unit TEXT,
    assignment     TEXT,                    -- as reported, e.g. 'B-centre', 'platelet (B'')'
    derivation     TEXT NOT NULL CHECK (derivation IN ('reported', 'calculated_by_authors',
                                                       'calculated_by_compiler', 'calculated_by_us',
                                                       'inferred', 'interpreted')),
    evidence_id    INTEGER REFERENCES evidence(id)
);

-- P, T, depth, residence temperature, ages: values that depend on a method and its inputs.
CREATE TABLE derived_parameter (
    id                       INTEGER PRIMARY KEY,
    inclusion_observation_id INTEGER REFERENCES inclusion_observation(id),
    diamond_observation_id   INTEGER REFERENCES diamond_observation(id),
    inclusion_set_id         INTEGER REFERENCES inclusion_set(id),
    quantity_code            TEXT NOT NULL REFERENCES quantity(code),
    original_text            TEXT NOT NULL,
    original_unit            TEXT,
    value                    DOUBLE PRECISION,
    uncertainty              DOUBLE PRECISION,
    uncertainty_type         TEXT CHECK (uncertainty_type IN ('1sd', '2sd', '1se', '2se', 'range', 'other')),
    method                   TEXT,          -- calibration or model, e.g. 'Harley (1984) + Brey & Koehler (1990)'
    assumptions              TEXT,          -- e.g. 'P fixed at 50 kbar'
    derivation               TEXT NOT NULL CHECK (derivation IN ('calculated_by_authors', 'calculated_by_compiler',
                                                                 'calculated_by_us', 'inferred', 'interpreted')),
    evidence_id              INTEGER NOT NULL REFERENCES evidence(id),
    workflow_status          TEXT NOT NULL DEFAULT 'pending_review'
                             CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                        'extraction_failed', 'pending_review', 'approved',
                                                        'rejected', 'superseded')),
    notes                    TEXT,
    CHECK (uncertainty IS NULL OR uncertainty_type IS NOT NULL),
    CHECK ((CASE WHEN inclusion_observation_id IS NULL THEN 0 ELSE 1 END)
         + (CASE WHEN diamond_observation_id   IS NULL THEN 0 ELSE 1 END)
         + (CASE WHEN inclusion_set_id         IS NULL THEN 0 ELSE 1 END) = 1)
);

CREATE TABLE derived_parameter_input (
    derived_parameter_id INTEGER NOT NULL REFERENCES derived_parameter(id),
    measurement_id       INTEGER NOT NULL REFERENCES measurement(id),
    PRIMARY KEY (derived_parameter_id, measurement_id)
);


-- ============ 6. Assertions: interpretations and descriptive properties (D-002) ============

-- One claim by one party: paragenesis, inferred original phase, garnet class, craton,
-- locality match, diamond size/shape/colour, touching/non-touching. Competing claims coexist.
CREATE TABLE assertion (
    id                       INTEGER PRIMARY KEY,
    inclusion_observation_id INTEGER REFERENCES inclusion_observation(id),
    diamond_observation_id   INTEGER REFERENCES diamond_observation(id),
    inclusion_set_id         INTEGER REFERENCES inclusion_set(id),
    property_code            TEXT NOT NULL REFERENCES property(code),
    value_text               TEXT NOT NULL, -- as stated, e.g. 'h', 'former bridgmanite', '-11+9'
    value_phase_id           INTEGER REFERENCES phase(id),      -- when the value is a phase
    value_locality_id        INTEGER REFERENCES locality(id),   -- when the value is a locality
    scheme                   TEXT,          -- classification scheme, e.g. 'Grutter et al. (2004)'
    asserted_by              TEXT NOT NULL CHECK (asserted_by IN ('authors', 'compiler', 'curator')),
    value_status             TEXT NOT NULL CHECK (value_status IN ('reported', 'not_reported', 'not_measured',
                                                                   'not_applicable', 'unknown', 'ambiguous',
                                                                   'below_detection')),
    derivation               TEXT NOT NULL CHECK (derivation IN ('reported', 'calculated_by_authors',
                                                                 'calculated_by_compiler', 'calculated_by_us',
                                                                 'inferred', 'interpreted')),
    evidence_id              INTEGER NOT NULL REFERENCES evidence(id),
    workflow_status          TEXT NOT NULL DEFAULT 'pending_review'
                             CHECK (workflow_status IN ('not_attempted', 'extracted', 'imported_unverified',
                                                        'extraction_failed', 'pending_review', 'approved',
                                                        'rejected', 'superseded')),
    notes                    TEXT,
    CHECK ((CASE WHEN inclusion_observation_id IS NULL THEN 0 ELSE 1 END)
         + (CASE WHEN diamond_observation_id   IS NULL THEN 0 ELSE 1 END)
         + (CASE WHEN inclusion_set_id         IS NULL THEN 0 ELSE 1 END) = 1)
);


-- ============ 7. Physical objects as clusters of observations (D-001) ============

-- Each observation maps to the smallest observation id reachable through approved links.
-- Count distinct cluster_id values to count physical inclusions / diamonds.
-- shortcut: recomputed on every query; fine for ~10^4 observations, materialize if it gets slow.
CREATE VIEW inclusion_cluster AS
WITH RECURSIVE
    edge (a, b) AS (
        SELECT observation_a, observation_b FROM inclusion_identity_link WHERE workflow_status = 'approved'
        UNION
        SELECT observation_b, observation_a FROM inclusion_identity_link WHERE workflow_status = 'approved'
    ),
    reach (start_id, node_id) AS (
        SELECT id, id FROM inclusion_observation
        UNION
        SELECT reach.start_id, edge.b FROM reach JOIN edge ON edge.a = reach.node_id
    )
SELECT start_id AS inclusion_observation_id, MIN(node_id) AS cluster_id
FROM reach GROUP BY start_id;

CREATE VIEW diamond_cluster AS
WITH RECURSIVE
    edge (a, b) AS (
        SELECT observation_a, observation_b FROM diamond_identity_link WHERE workflow_status = 'approved'
        UNION
        SELECT observation_b, observation_a FROM diamond_identity_link WHERE workflow_status = 'approved'
    ),
    reach (start_id, node_id) AS (
        SELECT id, id FROM diamond_observation
        UNION
        SELECT reach.start_id, edge.b FROM reach JOIN edge ON edge.a = reach.node_id
    )
SELECT start_id AS diamond_observation_id, MIN(node_id) AS cluster_id
FROM reach GROUP BY start_id;
